'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isndarrayLike = require( '@stdlib/assert/is-ndarray-like' );
var zeros = require( '@stdlib/ndarray/zeros' );
var pkg = require( './../package.json' ).name;
var concat1d = require( './../lib/assign.js' );


// MAIN //

bench( pkg+'::ndarrays', function benchmark( b ) {
	var values;
	var opts;
	var out;
	var v;
	var i;

	opts = {
		'dtype': 'float64'
	};

	values = [
		zeros( [ 32 ], opts ),
		zeros( [ 32 ], opts ),
		zeros( [ 32 ], opts ),
		zeros( [ 32 ], opts )
	];
	out = zeros( [ 128 ], opts );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = concat1d( values, out );
		if ( typeof v !== 'object' ) {
			b.fail( 'should return an ndarray' );
		}
	}
	b.toc();
	if ( !isndarrayLike( v ) ) {
		b.fail( 'should return an ndarray' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+'::ndarrays,casting', function benchmark( b ) {
	var values;
	var out;
	var v;
	var i;

	/* eslint-disable object-curly-newline */

	values = [
		zeros( [ 32 ], { 'dtype': 'float64' }),
		zeros( [ 32 ], { 'dtype': 'float32' }),
		zeros( [ 32 ], { 'dtype': 'int32' }),
		zeros( [ 32 ], { 'dtype': 'generic' })
	];
	out = zeros( [ 128 ], { 'dtype': 'generic' });

	/* eslint-enable object-curly-newline */

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = concat1d( values, out );
		if ( typeof v !== 'object' ) {
			b.fail( 'should return an ndarray' );
		}
	}
	b.toc();
	if ( !isndarrayLike( v ) ) {
		b.fail( 'should return an ndarray' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

